{"summary": "Detect table width in Answer sheet using border styles", "security_risk": "LOW", "command": "python3 - <<'PY'
import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx')
ws=wb['Answer']

def cell_has_border(cell):
    b=cell.border
    return any(getattr(side,'style',None) for side in [b.left,b.right,b.top,b.bottom])

for r in [11,12,13,20,21,22,23,24,3,4,5,6]:
    cols=[]
    for c in range(1,25):
        if cell_has_border(ws.cell(r,c)):
            cols.append(get_column_letter(c))
    print('row',r,'bordered',cols[:30])
PY"}

{"summary": "Extract 2025 gold reserve value and volume countries lists", "security_risk": "LOW", "command": "python3 - <<'PY'
import openpyxl,re
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
ws_val=wb['Value']
ws_vol=wb['Volume']

def country_from_desc(desc):
    if not isinstance(desc,str):
        return None
    return desc.split(':')[0].strip()

# find row with year 2025 in column A
row_2025=None
for r in range(1, ws_val.max_row+1):
    if str(ws_val.cell(r,1).value).strip()=='2025':
        row_2025=r
        break
print('Value row_2025',row_2025)
value_countries=[]
for c in range(3, ws_val.max_column+1):
    v=ws_val.cell(row_2025,c).value
    if isinstance(v,(int,float)):
        desc=ws_val.cell(1,c).value
        value_countries.append((country_from_desc(desc), c, v, desc))
print('Value countries with 2025 data:',len(value_countries))
for item in value_countries[:50]:
    print(item[0],'col',item[1],'value',item[2])

row_2025_vol=None
for r in range(1, ws_vol.max_row+1):
    if str(ws_vol.cell(r,1).value).strip()=='2025':
        row_2025_vol=r
        break
print('\nVolume row_2025',row_2025_vol)
vol_countries=[]
for c in range(3, ws_vol.max_column+1):
    v=ws_vol.cell(row_2025_vol,c).value
    if isinstance(v,(int,float)):
        desc=ws_vol.cell(1,c).value
        vol_countries.append((country_from_desc(desc), c, v, desc))
print('Volume countries with 2025 data:',len(vol_countries))
for item in vol_countries[:50]:
    print(item[0],'col',item[1],'value',item[2],'desc_tail',item[3].split('(')[-1])

# additional volume countries not in value
value_set=set([x[0] for x in value_countries])
add=[x for x in vol_countries if x[0] not in value_set]
print('\nAdditional volume-only countries:',[x[0] for x in add])
PY"}

{"summary": "Check which Step2 countries have 2025 total reserves values", "security_risk": "LOW", "command": "python3 - <<'PY'
import openpyxl
wb=openpyxl.load_workbook('/root/output/rar_result.xlsx', data_only=True)
ws_tr=wb['Total Reserves']
# find 2025 row
row_2025=None
for r in range(1,ws_tr.max_row+1):
    if str(ws_tr.cell(r,1).value).strip()=='2025':
        row_2025=r
        break
print('row_2025',row_2025)
# map cleaned country to value

def clean(desc):
    if not isinstance(desc,str): return None
    base=desc.split(':')[0].strip()
    for suffix in [' Intl Reserves',' International Reserves']:
        if base.endswith(suffix):
            base=base[:-len(suffix)].strip()
    return base

vals={}
for c in range(3,ws_tr.max_column+1):
    nm=clean(ws_tr.cell(1,c).value)
    v=ws_tr.cell(row_2025,c).value
    if nm:
        vals[nm]=v

step2=['Belarus','Czechia','Georgia','Latvia','Lithuania','Moldova','Slovakia','Ukraine','Uzbekistan']
for nm in step2:
    print(nm,'->',vals.get(nm))
PY"}

{"summary": "Replace invalid Excel empty-string literals '' with "" in formulas", "security_risk": "MEDIUM", "command": "python3 - <<'PY'
from pathlib import Path
import openpyxl
path=Path('/root/output/rar_result.xlsx')
wb=openpyxl.load_workbook(path)
repl_count=0
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and v.startswith('=') and "''" in v:
                cell.value = v.replace("''", '""')
                repl_count += 1
wb.save(path)
print('replaced formulas in',repl_count,'cells')
PY"}

